fn filter(v: Vec<Int>, div: Int) -> Vec<Int> {
    let out = vec()
    for x in v {
        if x % div == 0 {
            out = push(out, x)
        }
    }
    out
}

fn sum(v: Vec<Int>) -> Int {
    let acc = 0
    for x in v {
        acc = x + acc
    }
    acc
}

