fn parse_int(s: &Str) -> Option<Int> {
    let n = len(&s)
    if n == 0 {
        None
    } else {
        let c = chars(&s)
        let mut x = 0.to_int()
        for i in 0.to_int(n) {
            let d = c.get(i) - "0".get(0)
            if d < 0 || d > 9 {
                None
            } else {
                x = 10.to_int() * x + d
            }
        }
        Some(x)
    }
}

